def is_sorted(lst):
    # Check nonâdecreasing order
    if not all(lst[i - 1] <= lst[i] for i in range(1, len(lst))):
        return False

    # Count occurrences of each element
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
        if counts[item] > 2:  # more than two of the same value is not allowed
            return False

    return True
